  describe('handler', () => {
    it('calls the createLink method and shows messages', () => {
      getWrapper({
        setup: async ({ actions }) => {
          const { addLink } = useSharesStore()
          // link action
          await unref(actions)[0].handler({
            resources: [mock<Resource>({ canShare: () => true })],
